-- Phase 28: ledger line types and the ad accounts (SPEC core 4 "Dual-Layer Billing", core 8).
-- ledger_entries gains line_type (what a posting is; ADJUSTMENT when its journal named none, which
-- is every posting written before this migration: nothing is backfilled, the table is append-only)
-- and ad_purchase_id. The CHECK makes SPEC edge case 6 a database rule: an ad line names the
-- vendor's own purchase. Generated by drizzle-kit, unedited below this header.
--
-- ledger_line_type is created here (CREATE TYPE), so its values are usable at once. The new
-- ledger_account_type and ledger_transaction_kind values are ADDED to existing enums and are NOT
-- used in this file: PostgreSQL cannot use a new value of an existing enum before commit, and
-- Drizzle runs every pending migration in one transaction (see 0019). The AD_REVENUE and
-- AD_BUDGET_CLEARING accounts are therefore opened by LedgerService on first use, like
-- PAYOUT_CLEARING.
CREATE TYPE "public"."ledger_line_type" AS ENUM('ORDER_PROCEEDS', 'DELIVERY_FEE', 'PLATFORM_COMMISSION', 'SUBSCRIPTION_FEE', 'AD_FLAT_FEE', 'AD_ORDER_PREMIUM', 'AD_BUDGET_HOLD', 'AD_BUDGET_RELEASE', 'DISCOUNT_VENDOR_OFFER', 'DISCOUNT_CAMPAIGN_VENDOR_SHARE', 'DISCOUNT_CAMPAIGN_PLATFORM_SHARE', 'REFUND', 'RECHARGE', 'PAYOUT', 'ADJUSTMENT');--> statement-breakpoint
ALTER TYPE "public"."ledger_account_type" ADD VALUE 'AD_REVENUE';--> statement-breakpoint
ALTER TYPE "public"."ledger_account_type" ADD VALUE 'AD_BUDGET_CLEARING';--> statement-breakpoint
ALTER TYPE "public"."ledger_transaction_kind" ADD VALUE 'AD_PURCHASE';--> statement-breakpoint
ALTER TYPE "public"."ledger_transaction_kind" ADD VALUE 'AD_BUDGET_RELEASE';--> statement-breakpoint
ALTER TYPE "public"."ledger_transaction_kind" ADD VALUE 'AD_REFUND';--> statement-breakpoint
ALTER TABLE "ledger_entries" ADD COLUMN "line_type" "ledger_line_type" DEFAULT 'ADJUSTMENT' NOT NULL;--> statement-breakpoint
ALTER TABLE "ledger_entries" ADD COLUMN "ad_purchase_id" uuid;--> statement-breakpoint
ALTER TABLE "ledger_entries" ADD CONSTRAINT "ledger_entries_ad_purchase_id_ad_purchases_id_fk" FOREIGN KEY ("ad_purchase_id") REFERENCES "public"."ad_purchases"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "ledger_entries_ad_purchase_id_idx" ON "ledger_entries" USING btree ("ad_purchase_id") WHERE "ledger_entries"."ad_purchase_id" IS NOT NULL;--> statement-breakpoint
